pragma solidity >=0.8.0;

contract Int8DivProvenance {
    uint256 public count;
    int8 public a = type(int8).min;
    int8 public b = -1;
    int8 public last;

    function divStored() external returns (int8) {
        int8 r = a / b;
        last = r;
        count += 1;
        return r;
    }

    function divCalldata(int8 x, int8 y) external returns (int8) {
        int8 r = x / y;
        last = r;
        count += 1;
        return r;
    }
}
